import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ReactiveFormsModule, FormBuilder, FormGroup, Validators } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { ClienteService, Cliente } from '../cliente.service';
import { CatalogoService } from '../../../services/catalogo.service';

@Component({
  selector: 'app-cliente-detail',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './cliente-detail.component.html',
  styleUrls: ['./cliente-detail.component.css'],
})
export class ClienteDetailComponent implements OnInit {
  form: FormGroup;
  loading = false;
  submitted = false;
  error = '';
  isEditing = false;
  clienteId: number | null = null;
  tiposCliente: any[] = [];

  constructor(
    private formBuilder: FormBuilder,
    private clienteService: ClienteService,
    private catalogoService: CatalogoService,
    private route: ActivatedRoute,
    private router: Router,
  ) {
    this.form = this.formBuilder.group({
      codigo: ['', Validators.required],
      nombre: ['', Validators.required],
      direccion: ['', Validators.required],
      telefono: ['', Validators.required],
      correo: ['', [Validators.required, Validators.email]],
      id_tipo_cliente: [1, Validators.required],
      estado: [1, Validators.required],
    });
  }

  ngOnInit() {
    this.cargarTiposCliente();
    this.route.params.subscribe((params) => {
      if (params['id']) {
        this.clienteId = +params['id'];
        this.isEditing = true;
        setTimeout(() => this.cargarCliente(this.clienteId!), 100);
      }
    });
  }

  cargarTiposCliente() {
    this.catalogoService.getTiposCliente().subscribe({
      next: (data) => (this.tiposCliente = data),
      error: () => (this.tiposCliente = []),
    });
  }

  cargarCliente(id: number) {
    this.loading = true;
    this.clienteService.obtenerPorId(id).subscribe({
      next: (cliente) => {
        this.form.patchValue({
          codigo: cliente.codigo_cliente,
          nombre: cliente.nombre_comercial,
          direccion: cliente.direccion_empresa,
          telefono: cliente.telefono,
          correo: cliente.correo_electronico,
          id_tipo_cliente: cliente.id_tipo_cliente,
          estado: cliente.estado,
        });
        this.loading = false;
      },
      error: () => {
        this.error = 'Error al cargar cliente';
        this.loading = false;
      },
    });
  }

  get f() {
    return this.form.controls;
  }

  onSubmit() {
    this.submitted = true;
    this.error = '';

    if (this.form.invalid) {
      return;
    }

    this.loading = true;
    const cliente = this.form.value;

    if (this.isEditing && this.clienteId) {
      this.clienteService.actualizar(this.clienteId, cliente).subscribe({
        next: () => {
          this.router.navigate(['/clientes']);
        },
        error: () => {
          this.error = 'Error al actualizar cliente';
          this.loading = false;
        },
      });
    } else {
      this.clienteService.crear(cliente).subscribe({
        next: () => {
          this.router.navigate(['/clientes']);
        },
        error: () => {
          this.error = 'Error al crear cliente';
          this.loading = false;
        },
      });
    }
  }

  cancelar() {
    this.router.navigate(['/clientes']);
  }

  compareById(a: any, b: any): boolean {
    if (a === null || b === null) return a === b;
    return a === b;
  }
}
<div class="container">
  <div class="header">
    <h2>{{ isEditing ? 'Editar Cliente' : 'Nuevo Cliente' }}</h2>
  </div>

  <div *ngIf="error" class="alert alert-danger">
    {{ error }}
  </div>

  <div *ngIf="loading && isEditing" class="loading">
    Cargando cliente...
  </div>

  <form [formGroup]="form" (ngSubmit)="onSubmit()" *ngIf="!loading || !isEditing" class="form">
    <div class="form-group">
      <label for="codigo">Código</label>
      <input
        type="text"
        id="codigo"
        formControlName="codigo"
        class="form-control"
        [class.is-invalid]="submitted && f['codigo'].errors"
      />
      <div *ngIf="submitted && f['codigo'].errors" class="invalid-feedback">
        Código requerido
      </div>
    </div>

    <div class="form-group">
      <label for="nombre">Nombre</label>
      <input
        type="text"
        id="nombre"
        formControlName="nombre"
        class="form-control"
        [class.is-invalid]="submitted && f['nombre'].errors"
      />
      <div *ngIf="submitted && f['nombre'].errors" class="invalid-feedback">
        Nombre requerido
      </div>
    </div>

    <div class="form-group">
      <label for="direccion">Dirección</label>
      <input
        type="text"
        id="direccion"
        formControlName="direccion"
        class="form-control"
        [class.is-invalid]="submitted && f['direccion'].errors"
      />
      <div *ngIf="submitted && f['direccion'].errors" class="invalid-feedback">
        Dirección requerida
      </div>
    </div>

    <div class="form-group">
      <label for="telefono">Teléfono</label>
      <input
        type="text"
        id="telefono"
        formControlName="telefono"
        class="form-control"
        [class.is-invalid]="submitted && f['telefono'].errors"
      />
      <div *ngIf="submitted && f['telefono'].errors" class="invalid-feedback">
        Teléfono requerido
      </div>
    </div>

    <div class="form-group">
      <label for="correo">Correo</label>
      <input
        type="email"
        id="correo"
        formControlName="correo"
        class="form-control"
        [class.is-invalid]="submitted && f['correo'].errors"
      />
      <div *ngIf="submitted && f['correo'].errors" class="invalid-feedback">
        <div *ngIf="f['correo'].errors['required']">Correo requerido</div>
        <div *ngIf="f['correo'].errors['email']">Correo inválido</div>
      </div>
    </div>

    <div class="form-group">
      <label for="id_tipo_cliente">Tipo Cliente</label>
      <select id="id_tipo_cliente" formControlName="id_tipo_cliente" class="form-control" [compareWith]="compareById">
        <option [value]="null">Seleccionar tipo</option>
        <option *ngFor="let tipo of tiposCliente" [value]="tipo.id">{{ tipo.nombre }}</option>
      </select>
    </div>

    <div class="form-group">
      <label for="estado">Estado</label>
      <select id="estado" formControlName="estado" class="form-control">
        <option value="1">Activo</option>
        <option value="0">Inactivo</option>
      </select>
    </div>

    <div class="form-actions">
      <button type="submit" class="btn btn-primary" [disabled]="loading">
        {{ isEditing ? 'Actualizar' : 'Crear' }}
      </button>
      <button type="button" class="btn btn-secondary" (click)="cancelar()">
        Cancelar
      </button>
    </div>
  </form>
</div>
